    'review.tip.fixed_slot.d': 'Привяжите чтение к одному времени — 20 минут после завтрака или перед сном. Когда время закреплено, не нужно каждый день решать, читать ли.',
    'review.tip.habit_stack.t': 'Привязка к привычке',
    'review.tip.habit_stack.d': 'Читайте сразу после того, что и так делаете каждый день: кофе, дорога, ужин. «После чая — 10 страниц» работает лучше, чем «почитаю, когда будет время».',
    'review.tip.weekend_plan.t': 'План на выходные',
    'review.tip.weekend_plan.d': 'В выходные режим сбивается. Решите заранее, когда будете читать в субботу и воскресенье — например, утром, до телефона.',
    'review.tip.mid_month.t': 'Второе дыхание',
    'review.tip.mid_month.d': 'К середине месяца запал падает. Поставьте себе цель на 15-е число и отметьте её — второй старт даётся легче первого.',
    'review.tip.reading_room.t': 'Читальный зал',
    'review.tip.reading_room.d': 'Когда трудно начать, зайдите в читальный зал PowerBook и включите таймер: читать рядом с другими легче, а минуты сами попадут в «Сегодня».',
    'review.tip.start_strong.t': 'Сильный старт',
    'review.tip.start_strong.d': 'Первые дни задают тон всему кругу. Выберите книгу заранее и начните 1-го числа — пусть даже с 15 минут.',
    'review.tip.two_by_fifteen.t': 'Два раза по 15',
    'review.tip.two_by_fifteen.d': 'Если 30 минут подряд не выходит, разбейте их: 15 утром и 15 вечером. Дни с 10–20 минутами почти всегда можно добить до цели.',
    'review.tip.never_twice.t': 'Не пропускать дважды',
    'review.tip.never_twice.d': 'Пропустить день — нормально. Главное — не пропускать два подряд: после пропуска прочитайте хоть 10 минут на следующий день.',
    'review.tip.carry_book.t': 'Книга всегда с собой',
    'review.tip.carry_book.d': 'Держите книгу или файл в телефоне под рукой: очереди, дорога, ожидание — это 15–20 минут в день.',
    'review.tip.audiobooks.t': 'Аудио в дороге',
    'review.tip.audiobooks.d': 'В дни, когда не до бумаги, слушайте аудиоверсию в дороге или за делами — пустых дней станет меньше.',
    'review.tip.steady.t': 'Ровно, а не рывками',
    'review.tip.steady.d': 'Один день по три часа не заменит неделю по 30 минут. Лучше каждый день понемногу, чем догонять в выходные.',
    'review.tip.finish_line.t': 'До финиша',
    'review.tip.finish_line.d': 'Минут много, а дочитанных книг нет. Назначьте дату финиша или возьмите параллельно книгу покороче — законченная книга даёт силы на следующую.',
    'review.tip.look_back.t': 'Что помогало раньше',
    'review.tip.look_back.d': 'Этот круг дался тяжелее прошлого. Вспомните, что тогда помогало — время, место, книга — и верните это.',
    'review.tip.phone_away.t': 'Телефон в другой комнате',
    'review.tip.phone_away.d': 'На время чтения уберите телефон подальше или включите «Не беспокоить» — внимание держится дольше, страниц больше.',
    'review.tip.before_sleep.t': 'Перед сном',
    'review.tip.before_sleep.d': '15–20 минут книги перед сном вместо ленты — и день засчитан, и засыпать легче.',
    'review.tip.track_pages.t': 'Цель в страницах',
    'review.tip.track_pages.d': 'Иногда проще думать страницами: 20 страниц в день — это около 30 минут, а за год — пара десятков книг.',

