    'archetype.newcomer.kindred': 'Бенджамин Франклин',
    'archetype.newcomer.kindredWhy': 'Танысынан алған кітаптардан бастап, Америкадағы алғашқы ақылы кітапхананы ашумен аяқтады.',
    'archetype.comeback.title': 'Оралу',
