    'archetype.comeback.kindred': 'Мигель де Сервантес',
    'archetype.comeback.kindredWhy': 'Бес жыл тұтқын, ұзақ үнсіздік — содан алпысқа таяғанда «Дон Кихот».',
    'archetype.ironclad.title': 'Үзілмейтін тізбек',
