    'archetype.ironclad.kindred': 'Иммануил Кант',
    'archetype.ironclad.kindredWhy': 'Кёнигсберг аңызы бойынша, көршілері оның күнделікті серуеніне қарап сағаттарын түзеген.',
    'archetype.deep_diver.title': 'Терең сүңгу',
    'archetype.deep_diver.description': 'Күндеріңіздің {long_pct}%-ы бір жарым сағаттан ұзақ. Сіз кітапқа көз жүгіртпейсіз — кітапқа кетесіз.',
    'archetype.deep_diver.kindred': 'Мишель де Монтень',
    'archetype.deep_diver.kindredWhy': 'Мың кітабы бар мұнараға жабылып, сол жерден «Тәжірибелерімен» шықты.',
    'archetype.marathoner.title': 'Ұзақ тыныс',
    'archetype.marathoner.description': 'Оқыған күні орташа {avg_minutes} минут. Бұл бірер бет емес, бүтін қашықтық.',
    'archetype.marathoner.kindred': 'Умберто Эко',
    'archetype.marathoner.kindredWhy': 'Үйінде отыз мың том ұстады және кітапханадағы ең құндысы — оқылмағаны деп қайталайтын.',
    'archetype.metronome.title': 'Метроном',
    'archetype.metronome.description': 'Тұрақтылық {consistency_pct}%, минуттарыңыз күннен күнге дерлік өзгермейді. Сіз сағат тетігіндей оқисыз.',
    'archetype.metronome.kindred': 'Чарльз Дарвин',
    'archetype.metronome.kindredWhy': 'Күн тәртібін минутымен ұстады: жұмыс, «ой соқпағымен» серуен, кешкі дауыстап оқу.',
    'archetype.norm_keeper.title': 'Дәл өлшем',
    'archetype.norm_keeper.description': 'Күндеріңіздің {norm_pct}%-ы — отыз минуттан сәл асады. Нормаңызды дәл аласыз, артығын шашпайсыз.',
    'archetype.norm_keeper.kindred': 'Сенека',
    'archetype.norm_keeper.kindredWhy': 'Аз авторды, бірақ соңына дейін оқуға кеңес берген: «бәрінде болу — еш жерде болмау».',
    'archetype.deadline_dancer.title': 'Фиништік серпін',
    'archetype.deadline_dancer.description': 'Минуттарыңыздың {late_pct}%-ы айдың соңғы онкүндігіне түседі. Раундты соңғы сәтте жабасыз — бірақ жабасыз.',
    'archetype.deadline_dancer.kindred': 'Фёдор Достоевский',
    'archetype.deadline_dancer.kindredWhy': 'Келісімшарттағы мерзімге үлгеру үшін «Ойыншыны» жиырма алты күнде жазып шықты.',
    'archetype.fast_starter.title': 'Бірден қарқын',
    'archetype.fast_starter.description': 'Минуттарыңыздың {early_pct}%-ын раундтың алғашқы он күнінде жинайсыз. Басқалар қызып жатқанда сіз жүріп кеткенсіз.',
    'archetype.fast_starter.kindred': 'Виктор Гюго',
    'archetype.fast_starter.kindredWhy': 'Күндік нормасын орындамай үйден шықпас үшін киімін шкафқа құлыптап тастайтын.',
    'archetype.weekday_loyalist.title': '{weekday} — сіздің оқу күніңіз',
    'archetype.weekday_loyalist.description': 'Оқуыңыздың басым бөлігі {weekday} күндеріне түседі. Сізде өз күніңіз бар.',
    'archetype.weekday_loyalist.kindred': 'Хорхе Луис Борхес',
    'archetype.weekday_loyalist.kindredWhy': 'Оқыды да, жұмыс істеді де бір жерде — өзі басқарған Ұлттық кітапханада.',
    'archetype.weekend_reader.title': 'Демалыс тыныштығы',
    'archetype.weekend_reader.description': 'Минуттарыңыздың {weekend_pct}%-ы — сенбі мен жексенбі. Жұмыс күндері тірлікке кетеді, кітап тыныштықты күтеді.',
    'archetype.weekend_reader.kindred': 'Шәкәрім Құдайбердіұлы',
    'archetype.weekend_reader.kindredWhy': 'Тауға кетіп, жылдар бойы жұрттың шуынан алыста оқып, жазып жүрді.',
    'archetype.finisher.title': 'Соңғы бетке дейін',
    'archetype.finisher.description': 'Раундтарыңыздың {finish_pct}%-ында кітапты аяқтадыңыз. Бастағаныңыз аяғына жетеді.',
    'archetype.finisher.kindred': 'Лев Толстой',
    'archetype.finisher.kindredWhy': '«Оқу шеңбері» жинағын құрастырды — жыл бойғы әр күнге өзі оқығанынан таңдап.',
    'archetype.omnivore.title': 'Бәрін оқитын',
    'archetype.omnivore.description': '{books} аяқталған кітап. Сізді бір сөре ұстап тұра алмайды.',
    'archetype.omnivore.kindred': 'Теодор Рузвельт',
    'archetype.omnivore.kindredWhy': 'Замандастарының айтуынша, күніне бір кітап оқыған — антика тарихшыларынан вестерндерге дейін.',
    'archetype.on_the_rise.title': 'Өрлеу қисығы',
