    'archetype.on_the_rise.kindred': 'Малкольм Икс',
    'archetype.on_the_rise.kindredWhy': 'Оқуды шын мәнінде түрмеде үйренді — бүкіл сөздікті қолымен көшіріп шығып.',
    'archetype.steady.title': 'Тұрақты жалын',
