    'archetype.steady.kindred': 'Харуки Мураками',
    'archetype.steady.kindredWhy': 'Күнде бір қалып: ерте тұру, жұмыс, жүгіру, ұйқы. Жылдар бойы.',
    'archetype.sprinter.title': 'Жарқылмен',
    'archetype.sprinter.description': 'Қуатты күндер тыныштықпен алмасады. Сіз біркелкі ағыспен емес, разрядпен оқисыз.',
    'archetype.sprinter.kindred': 'Оноре де Бальзак',
    'archetype.sprinter.kindredWhy': 'Түн ортасында үстелге отырып, он бес сағат қатарынан жұмыс істеп, сосын әлсіреп құлайтын.',
    'archetype.slow_burn.title': 'Тыныш от',
    'archetype.slow_burn.description': 'Күніне орташа {avg_minutes} минут — көп емес, бірақ үзіліссіз. Аз-аздан, өте ұзақ.',
    'archetype.slow_burn.kindred': 'Джейн Остин',
    'archetype.slow_burn.kindredWhy': 'Ортақ қонақ бөлмесінде үзік-үзік жазып оқыды; есік сықырласа, парақтарын жасыратын.',
    'archetype.veteran.title': 'Раундтар ақсақалы',
