    'archetype.newcomer.title': 'First Pages',
    'archetype.newcomer.description': 'You are just starting — a couple more circles and a pattern will show in your minutes.',
    'archetype.newcomer.kindred': 'Benjamin Franklin',
    'archetype.newcomer.kindredWhy': 'He began with books borrowed from friends and ended up founding the first subscription library in America.',
    'archetype.comeback.title': 'The Return',
    'archetype.comeback.description': 'There is a {gap_days}-day silence in your history — and you came back. That is rarer than an unbroken run.',
    'archetype.comeback.kindred': 'Miguel de Cervantes',
    'archetype.comeback.kindredWhy': 'Five years of captivity, a long silence, and then Don Quixote, written when he was nearly sixty.',
    'archetype.ironclad.title': 'Unbroken Chain',
    'archetype.ironclad.description': 'Your best run is {streak} days straight. For most people a chain like that snaps in the second week.',
    'archetype.ironclad.kindred': 'Immanuel Kant',
    'archetype.ironclad.kindredWhy': 'Legend has it the neighbours in Konigsberg set their clocks by his daily walk.',
    'archetype.deep_diver.title': 'Deep Dive',
    'archetype.deep_diver.description': '{long_pct}% of your days run past an hour and a half. You do not glance at a book, you disappear into it.',
    'archetype.deep_diver.kindred': 'Michel de Montaigne',
    'archetype.deep_diver.kindredWhy': 'He shut himself in a tower with a thousand books and came back out with the Essays.',
    'archetype.marathoner.title': 'Long Breath',
    'archetype.marathoner.description': 'An average of {avg_minutes} minutes on a reading day. That is a distance, not a visit.',
    'archetype.marathoner.kindred': 'Umberto Eco',
    'archetype.marathoner.kindredWhy': 'He kept thirty thousand volumes at home and liked to say the unread ones are the valuable part.',
    'archetype.metronome.title': 'The Metronome',
    'archetype.metronome.description': '{consistency_pct}% consistency, and your daily minutes barely move. You read like clockwork.',
    'archetype.metronome.kindred': 'Charles Darwin',
    'archetype.metronome.kindredWhy': 'He lived to the minute: work, a turn around the Sandwalk, reading aloud in the evening.',
    'archetype.norm_keeper.title': 'Exact Measure',
    'archetype.norm_keeper.description': '{norm_pct}% of your days land on thirty-odd minutes. You take the norm and nothing more.',
    'archetype.norm_keeper.kindred': 'Seneca',
    'archetype.norm_keeper.kindredWhy': 'He advised reading few authors but to the end: to be everywhere is to be nowhere.',
    'archetype.deadline_dancer.title': 'The Last Ten Days',
    'archetype.deadline_dancer.description': '{late_pct}% of your minutes fall in the final third of the month. You close the circle at the whistle — but you close it.',
    'archetype.deadline_dancer.kindred': 'Fyodor Dostoevsky',
    'archetype.deadline_dancer.kindredWhy': 'He wrote The Gambler in twenty-six days to meet a date written into a contract.',
    'archetype.fast_starter.title': 'Off the Mark',
    'archetype.fast_starter.description': 'You take {early_pct}% of your minutes in the first ten days of a circle. You are running while others warm up.',
    'archetype.fast_starter.kindred': 'Victor Hugo',
    'archetype.fast_starter.kindredWhy': 'He locked his clothes away so he could not leave the house before the day quota was done.',
    'archetype.weekday_loyalist.title': '{weekday} is your reading day',
    'archetype.weekday_loyalist.description': 'The bulk of your reading lands on {weekday}. You have a day of the week that is yours.',
    'archetype.weekday_loyalist.kindred': 'Jorge Luis Borges',
    'archetype.weekday_loyalist.kindredWhy': 'He read and worked in one and the same place: the National Library he himself directed.',
    'archetype.weekend_reader.title': 'The Weekend Quiet',
    'archetype.weekend_reader.description': '{weekend_pct}% of your minutes are Saturday and Sunday. Weekdays go to the world, books wait for the quiet.',
    'archetype.weekend_reader.kindred': 'Shakarim Kudaiberdiuly',
    'archetype.weekend_reader.kindredWhy': 'He withdrew into the mountains and spent years reading and writing far from anyone.',
    'archetype.finisher.title': 'To the Last Page',
    'archetype.finisher.description': 'You finished a book in {finish_pct}% of your circles. What you start, you end.',
    'archetype.finisher.kindred': 'Leo Tolstoy',
    'archetype.finisher.kindredWhy': 'He assembled A Calendar of Wisdom, a year of daily pages drawn from everything he had read.',
    'archetype.omnivore.title': 'The Omnivore',
    'archetype.omnivore.description': '{books} books finished. One shelf was never going to hold you.',
    'archetype.omnivore.kindred': 'Theodore Roosevelt',
    'archetype.omnivore.kindredWhy': 'By contemporary accounts he went through a book a day, from ancient historians to dime westerns.',
    'archetype.on_the_rise.title': 'The Rising Curve',
    'archetype.on_the_rise.description': 'You now read {second_half_avg} minutes against {first_half_avg} when you started. The curve is going up.',
    'archetype.on_the_rise.kindred': 'Malcolm X',
    'archetype.on_the_rise.kindredWhy': 'He truly learned to read in prison, copying out an entire dictionary by hand, page after page.',
    'archetype.steady.title': 'Steady Flame',
    'archetype.steady.description': '{consistency_pct}% consistency, with no spikes and no collapses. You neither race nor go out.',
    'archetype.steady.kindred': 'Haruki Murakami',
    'archetype.steady.kindredWhy': 'The same day, every day: up early, work, run, sleep. For years.',
    'archetype.sprinter.title': 'In Bursts',
    'archetype.sprinter.description': 'Powerful days give way to quiet ones. You read in discharges, not in a steady current.',
    'archetype.sprinter.kindred': 'Honore de Balzac',
    'archetype.sprinter.kindredWhy': 'He sat down at midnight, worked fifteen hours at a stretch, and then collapsed.',
    'archetype.slow_burn.title': 'Slow Burn',
    'archetype.slow_burn.description': 'An average of {avg_minutes} minutes a day — not much, but almost never missed. A little, for a very long time.',
    'archetype.slow_burn.kindred': 'Jane Austen',
    'archetype.slow_burn.kindredWhy': 'She wrote and read in snatches in the family sitting room, hiding the pages when the door creaked.',
    'archetype.veteran.title': 'The Old Hand',
    'archetype.veteran.description': '{rounds} circles behind you. You have been here longer than most books on the shelf.',
    'archetype.veteran.kindred': 'Abai Kunanbaiuly',
    'archetype.veteran.kindredWhy': 'He translated Pushkin, Lermontov and Goethe so they could be read in Kazakh, and gathered readers around him.',
    'archetype.reader.title': 'Own Rhythm',
    'archetype.reader.description': 'A solid habit with no extremes: you simply read, and it works.',
    'archetype.reader.kindred': 'Ray Bradbury',
    'archetype.reader.kindredWhy': 'For ten years he went to the library three days a week, and said it was the library that taught him.',
