    'wl.promptRegTitle': 'Sign-up for the {month} circle is open',
    'wl.promptRegText': 'A month of reading 30 minutes a day with the PowerBook community. Sign-up is open until {date} — {n} days left.',
    'wl.promptRegToday': 'A month of reading 30 minutes a day with the PowerBook community. Sign-up is open — join in time.',
